package cn.kongj.blackstone;
import android.content.Context;import android.graphics.*;import android.view.View;
/** Skill-only HUD diagram; no character names, accounts, or world screenshots. */
final class SkillGuideView extends View {
 final Paint paint=new Paint(3);final Bitmap[] icons;final int[][] points;final String[] labels;
 SkillGuideView(Context context,int profession){super(context);if(profession==RolePlan.SAGE){points=new int[][]{{1720,1290},{1900,1290},{1945,1090},{2010,890}};labels=new String[]{"大招","减益","增益","控制"};}else if(profession==RolePlan.PRIEST){points=new int[][]{{1720,1290}};labels=new String[]{"天堂审判"};}else if(profession==RolePlan.ELEMENTALIST){points=new int[][]{{1720,1290},{2190,805}};labels=new String[]{"大招","控制"};}else{points=new int[][]{{1720,1290}};labels=new String[]{"大招"};}icons=new Bitmap[points.length];for(int i=0;i<icons.length;i++)try(java.io.InputStream in=context.getAssets().open("guide-"+profession+"-"+i+".png")){icons[i]=BitmapFactory.decodeStream(in);}catch(Exception ignored){}setContentDescription(RolePlan.PROFESSIONS[profession]+"技能位置示意图，"+android.text.TextUtils.join("、",labels));}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(0xff1f303b);float scale=Math.min(getWidth()/900f,getHeight()/710f);canvas.save();canvas.translate((getWidth()-900*scale)/2,(getHeight()-710*scale)/2);canvas.scale(scale,scale);paint.setStyle(Paint.Style.FILL);paint.setColor(0xffd9e6e7);paint.setTextSize(25);canvas.drawText("游戏右下角技能区 · 按图放置",28,32,paint);for(int[] point:FlowPolicy.SKILLS){float x=point[0]-1640,y=point[1]-720;if(x<40||x>850||y<50)continue;paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(3);paint.setColor(0xff516370);canvas.drawCircle(x,y,57,paint);}paint.setStyle(Paint.Style.STROKE);paint.setColor(0xff516370);canvas.drawCircle(600,430,105,paint);paint.setStyle(Paint.Style.FILL);paint.setTextSize(26);canvas.drawText("普通攻击",545,438,paint);for(int i=0;i<points.length;i++){float x=points[i][0]-1640,y=points[i][1]-720;paint.setStyle(Paint.Style.FILL);paint.setColor(0xff16313c);canvas.drawCircle(x,y,68,paint);if(icons[i]!=null)canvas.drawBitmap(icons[i],null,new RectF(x-61,y-61,x+61,y+61),paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(5);paint.setColor(0xff7ee1c4);canvas.drawCircle(x,y,67,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(Color.WHITE);paint.setTextSize(25);paint.setTextAlign(Paint.Align.CENTER);canvas.drawText(labels[i],x,y+99,paint);paint.setTextAlign(Paint.Align.LEFT);}canvas.restore();}
}
